    "Novas estações": "New stations",
    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "New installations use Brazilian prefixes by default. The graphical editor can combine filters for Brazil, radius, geographic area, prefixes, exact callsigns, and packet types, while keeping the manual field always available.",
    "novo": "new",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "New recipient: __ARG0__. There are no recorded conversations with this address yet.",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "The application remains active while the indicators are being prepared.",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "The client does not assign a radio model based solely on the USB chipset. When Windows does not specify the actual model, the interface is displayed generically, for example.",
    "O destino deixou de possuir rota RF completa no período selecionado.": "The destination no longer has a complete RF route during the selected period.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi uses duplicate suppression, loop blocking, hop limiting, and a priority queue for messages/ACK/REJ.",
    "O filtro abreviado r/RAIO exige latitude e longitude configuradas.": "The shorthand filter r/RAIO requires latitude and longitude to be configured.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "The filter APRS-IS is empty. Depending on the server and port used, the client may receive a much higher volume of traffic, including the entire flow available on this connection.\n\nDo you want to continue without a filter?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "The graph uses messages, ACK/REJ, and presence RF to prioritize useful traffic and avoid unnecessary repetition. It does not arbitrarily rewrite third-party paths or invent links RF.",
