    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Las nuevas instalaciones utilizan prefijos brasileños por defecto. El editor gráfico permite combinar filtros para Brasil, radio, área geográfica, prefijos, indicativos exactos y tipos de paquetes, manteniendo siempre disponible el campo manual.",
