    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "El archivo exportado JSON contiene la contraseña APRS-IS en texto legible. Guárdelo en un lugar seguro.",
    "O novo cálculo falhou; mantendo o último ranking válido.": "El nuevo cálculo falló; la clasificación anterior sigue siendo válida.",
