    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "La nueva plantilla de instalación recibe identificadores brasileños. El campo sigue siendo totalmente editable para los filtros manuales APRS-IS.",
