    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Les nouvelles installations utilisent par défaut les préfixes brésiliens. L'éditeur graphique permet de combiner des filtres pour le Brésil, le rayon, la zone géographique, les préfixes, les indicatifs d'appel exacts et les types de paquets, tout en laissant le champ manuel toujours accessible.",
    "novo": "nouveau",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "Nouveau destinataire : __ARG0__. Aucune conversation n'a encore été enregistrée avec cette adresse.",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "L'application reste active pendant la préparation des indicateurs.",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Le fichier exporté contient le code d'accès APRS-IS en caractères lisibles. Conservez-le en lieu sûr.",
