    "O botão": "Le bouton",
    "O cabeçalho informa se você está usando a": "L'en-tête vous indique si vous utilisez le",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "Le client n'attribue pas de modèle radio uniquement en fonction du chipset USB. Lorsque Windows ne spécifie pas le modèle exact, l'interface est affichée de manière générique, par exemple.",
    "O compositor aceita mensagens longas. Use": "Le compositeur accepte les messages longs. Utilisez",
    "O destino deixou de possuir rota RF completa no período selecionado.": "La destination ne dispose plus d'un itinéraire complet RF pendant la période sélectionnée.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi utilise la suppression des doublons, le blocage des boucles, la limitation des sauts et une file d'attente prioritaire pour les messages/ACK/REJ.",
    "O filtro abreviado r/RAIO exige latitude e longitude configuradas.": "Le filtre abrégé r/RAIO nécessite la configuration de la latitude et de la longitude.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "Le filtre APRS-IS est vide. Selon le serveur et le port utilisés, le client peut recevoir un volume de trafic beaucoup plus important, voire la totalité du flux disponible sur cette connexion.\n\nVoulez-vous continuer sans filtre ?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "Le graphe utilise les messages (ACK/REJ) et la présence (RF) pour prioriser le trafic utile et éviter les répétitions inutiles. Il ne réécrit pas arbitrairement les chemins tiers ni n'invente de liens (RF).",
    "O grupo do boletim deve ter de 1 a 5 caracteres alfanuméricos.": "Le groupe du bulletin doit contenir de 1 à 5 caractères alphanumériques.",
    "O grupo não possui estações.": "Le groupe ne possède aucune station.",
    "O identificador do boletim/anúncio deve ser 0-9 ou A-Z.": "L'identifiant de la newsletter/annonce doit être un chiffre 0-9 ou une lettre de A à Z.",
    "O idioma é aplicado imediatamente à interface.": "Le langage est appliqué immédiatement à l'interface.",
    "O início precisa ser anterior ao fim.": "Le début doit précéder la fin.",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "Le programme d'installation et le fichier EXE portable utilisent la même base de données locale.",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Le fichier exporté JSON contient le code d'accès APRS-IS en caractères lisibles. Conservez-le en lieu sûr.",
    "O novo cálculo falhou; mantendo o último ranking válido.": "Le nouveau calcul a échoué ; le dernier classement reste valable.",
