    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "Le nouveau modèle d'installation utilise des identifiants brésiliens. Le champ reste entièrement modifiable pour les filtres manuels APRS-IS.",
