    "Se o filtro for deixado vazio, o programa pedirá confirmação antes de salvar. Dependendo do servidor/porta, isso pode resultar em um fluxo de tráfego muito amplo.": "Si le filtre est laissé vide, le programme demandera une confirmation avant l'enregistrement. Selon le serveur et le port, cela peut engendrer un trafic réseau très important.",
