    "A alteração é aplicada imediatamente e fica salva após clicar em Salvar.": "Die Änderung wird sofort angewendet und nach dem Klicken auf „Speichern“ gespeichert.",
    "A altitude ainda está em 0 m porque não foi obtida automaticamente. O beacon será enviado, mas recomendamos informar a altitude real.": "Die Höhe wird weiterhin mit 0 m angezeigt, da sie nicht automatisch ermittelt wurde. Das Notsignal wird gesendet, wir empfehlen jedoch, die tatsächliche Höhe zu melden.",
