    "A cadeia representa alcançabilidade RF histórica composta por enlaces observados individualmente e compatíveis pelas coordenadas dos nós.": "Die Kette repräsentiert die historische Erreichbarkeit RF, die aus einzeln beobachteten und anhand der Koordinaten der Knoten kompatibelen Verbindungen besteht.",
    "A camada mostra apenas terreno com altitude igual ou superior à cota escolhida no slider.": "Die Ebene zeigt nur Gelände mit einer Höhe an, die gleich oder größer als die im Schieberegler ausgewählte Höhe ist.",
