    "por padrão, além de janelas em horas/dias, legenda dos tipos de linhas e animação de tráfego no mapa.": "Standardmäßig werden neben stündlichen/täglichen Zeitfenstern auch eine Legende für Linientypen und Verkehrsanimationen auf der Karte angezeigt.",
