    "prioriza APRS-IS para preservar o comportamento tradicional do cliente e usa RF direto somente quando o APRS-IS estiver indisponível e o TNC estiver pronto para TX.": "Es priorisiert APRS-IS, um das traditionelle Kundenverhalten zu erhalten, und verwendet RF direkt nur dann, wenn APRS-IS nicht verfügbar ist und TNC zur Übertragung bereit ist.",
