    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Le nuove installazioni utilizzano di default i prefissi brasiliani. L'editor grafico consente di combinare filtri per Brasile, raggio, area geografica, prefissi, nominativi esatti e tipi di pacchetto, mantenendo sempre disponibile il campo per l'inserimento manuale.",
