    "O aplicativo continua ativo enquanto os indicadores são preparados.": "L'applicazione rimane attiva durante la preparazione degli indicatori.",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Il file esportato contiene il codice di accesso APRS-IS in formato leggibile. Conservalo in un luogo sicuro.",
