    "O botão": "Il pulsante",
    "O cabeçalho informa se você está usando a": "L'intestazione ti dice se stai usando il",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "Il client non assegna un modello radio basandosi esclusivamente sul chipset USB. Quando Windows non specifica il modello effettivo, l'interfaccia viene visualizzata in modo generico, ad esempio.",
    "O compositor aceita mensagens longas. Use": "Il compositore accetta messaggi lunghi. Utilizzare",
    "O destino deixou de possuir rota RF completa no período selecionado.": "La destinazione non dispone più di un percorso RF completo durante il periodo selezionato.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi utilizza la soppressione dei duplicati, il blocco dei cicli, la limitazione dei salti e una coda di priorità per i messaggi/ACK/REJ.",
    "O filtro abreviado r/RAIO exige latitude e longitude configuradas.": "Il filtro abbreviato r/RAIO richiede la configurazione di latitudine e longitudine.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "Il filtro APRS-IS è vuoto. A seconda del server e della porta utilizzati, il client potrebbe ricevere un volume di traffico molto più elevato, incluso l'intero flusso disponibile su questa connessione.\n\nSi desidera continuare senza filtro?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "Il grafico utilizza messaggi, ACK/REJ, e presenza RF per dare priorità al traffico utile ed evitare ripetizioni non necessarie. Non riscrive arbitrariamente percorsi di terze parti né inventa collegamenti RF.",
    "O grupo do boletim deve ter de 1 a 5 caracteres alfanuméricos.": "Il gruppo di messaggi deve contenere da 1 a 5 caratteri alfanumerici.",
    "O grupo não possui estações.": "Il gruppo non possiede alcuna stazione.",
    "O identificador do boletim/anúncio deve ser 0-9 ou A-Z.": "L'identificativo della newsletter/annuncio deve essere compreso tra 0 e 9 oppure tra A e Z.",
    "O idioma é aplicado imediatamente à interface.": "Il linguaggio viene applicato immediatamente all'interfaccia.",
    "O início precisa ser anterior ao fim.": "L'inizio deve precedere la fine.",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "Il programma di installazione e il file EXE portatile utilizzano lo stesso database locale.",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Il file JSON esportato contiene il codice di accesso APRS-IS in formato leggibile. Conservalo in un luogo sicuro.",
