    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "Il nuovo modello di installazione accetta identificativi brasiliani. Il campo rimane completamente modificabile per i filtri manuali APRS-IS.",
