    "PY2AAA-9, PU2BBB-7, PT2CCC": "PY2AAA-9, PU2BBB-7, PT2CCC",
    "pyserial não está instalado; KISS Serial indisponível.": "pyserial non è installato; KISS Serial non è disponibile.",
    "pyserial não está instalado.": "pyserial non è installato.",
    "Quando chega uma nova mensagem para sua estação e a aba Mensagens já está aberta, o programa usa um aviso pequeno e não bloqueante, que fecha automaticamente pelo tempo definido em Configuração. Fora da aba Mensagens, permanece o aviso completo com opção de responder.": "Quando arriva un nuovo messaggio per la tua stazione e la scheda Messaggi è già aperta, il programma utilizza una piccola notifica non bloccante che si chiude automaticamente dopo il tempo definito nelle Impostazioni. Al di fuori della scheda Messaggi, la notifica completa rimane visibile con l'opzione per rispondere.",
    "Quando houver atualização, clicar no aviso inicia o download do pacote compatível com a plataforma. O arquivo é validado antes da instalação.": "Quando è disponibile un aggiornamento, cliccando sulla notifica si avvierà il download del pacchetto compatibile con la tua piattaforma. Il file verrà convalidato prima dell'installazione.",
    "Quando houver nova versão, o cliente seleciona o pacote compatível com a plataforma, valida o download e usa um updater auxiliar para encerrar a versão atual, instalar e abrir a nova versão.": "Quando è disponibile una nuova versione, il client seleziona il pacchetto compatibile con la piattaforma, convalida il download e utilizza un programma di aggiornamento ausiliario per chiudere la versione corrente, installare e aprire la nuova versione.",
    "quando necessário. A configuração oferece sugestões regionais e continua aceitando servidor manual.": "Se necessario, la configurazione offre suggerimenti regionali e continua ad accettare impostazioni manuali del server.",
