    "A cadeia representa alcançabilidade RF histórica composta por enlaces observados individualmente e compatíveis pelas coordenadas dos nós.": "このチェーンは、ノードの座標によって個別に観測され互換性のあるリンクで構成される、歴史的な到達可能性RFを表します。",
