    "A lista mostra indicativo, última recepção, distância, velocidade, curso, altitude e informações conhecidas.": "リストには、コールサイン、最終受信時刻、距離、速度、進路、高度、および既知の情報が表示されます。",
    "A malha é muito densa e a busca atingiu o limite de segurança. Os enlaces elegíveis continuam visíveis; refine o período se precisar de mais rotas.": "ネットワーク密度が非常に高く、検索が安全限界に達しました。有効なリンクは引き続き表示されます。より多くの経路が必要な場合は、期間を絞り込んでください。",
