    "Nova mensagem": "新しいメッセージ",
    "Nova mensagem de ": "新しいメッセージ",
    "Nova versão v__ARG0__ disponível": "新バージョンv__ARG0__が利用可能です",
    "Novas estações": "新駅",
    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "新規インストールでは、デフォルトでブラジルのプレフィックスが使用されます。グラフィカルエディタでは、ブラジル、半径、地理的エリア、プレフィックス、正確なコールサイン、パケットタイプなどのフィルタを組み合わせることができ、手動入力フィールドは常に利用可能です。",
    "novo": "新しい",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "新しい受信者：__ARG0__。このアドレスとの会話記録はまだありません。",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "指標の準備中も、アプリケーションはアクティブな状態を維持します。",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "エクスポートされたファイルには、パスコード「APRS-IS」が判読可能なテキストで含まれています。安全な場所に保管してください。",
    "O banco SQLite fica em:": "SQLiteデータベースは以下の場所にあります。",
    "O botão": "ボタン",
    "O cabeçalho informa se você está usando a": "ヘッダーには、",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "クライアントは、USBチップセットのみに基づいて無線モデルを割り当てません。Windowsが実際のモデルを指定しない場合、インターフェースは汎用的に表示されます。",
    "O compositor aceita mensagens longas. Use": "作曲者は長いメッセージを受け付けます。",
    "O destino deixou de possuir rota RF completa no período selecionado.": "選択した期間中、目的地には完全なRFルートが存在しません。",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi は、メッセージ/ACK/REJ に対して重複抑制、ループブロック、ホップ制限、および優先度キューを使用します。",
    "O filtro abreviado r/RAIO exige latitude e longitude configuradas.": "短縮フィルタr/RAIOを使用するには、緯度と経度を設定する必要があります。",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "フィルタAPRS-ISは空です。使用するサーバーとポートによっては、クライアントは、この接続で利用可能なすべてのトラフィックを含む、はるかに大量のトラフィックを受信する可能性があります。\n\nフィルタなしで続行しますか？",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "このグラフは、メッセージACK/REJとプレゼンスRFを使用して、有用なトラフィックを優先し、不要な繰り返しを回避します。サードパーティのパスを恣意的に書き換えたり、リンクRFを生成したりすることはありません。",
    "O grupo do boletim deve ter de 1 a 5 caracteres alfanuméricos.": "掲示板グループには、1～5文字の英数字を含める必要があります。",
    "O grupo não possui estações.": "同グループは放送局を一切所有していない。",
    "O identificador do boletim/anúncio deve ser 0-9 ou A-Z.": "ニュースレター／お知らせの識別子は、0～9またはA～Zのいずれかでなければなりません。",
    "O idioma é aplicado imediatamente à interface.": "その言語はインターフェースに即座に適用される。",
    "O início precisa ser anterior ao fim.": "終わりの前には始まりがなければならない。",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "インストーラーとポータブルEXEファイルは、同じローカルデータベースを使用します。",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "エクスポートされたファイルJSONには、パスコードAPRS-ISが判読可能なテキスト形式で含まれています。安全な場所に保管してください。",
    "O novo cálculo falhou; mantendo o último ranking válido.": "新しい計算は失敗しました。前回のランキングは引き続き有効です。",
    "O pacote compatível será baixado, validado e instalado automaticamente.": "互換性のあるパッケージは自動的にダウンロード、検証、インストールされます。",
    "O pacote Linux TAR.GZ não contém o executável esperado.": "LinuxのTAR.GZパッケージには、期待される実行ファイルが含まれていません。",
    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "新規設置の場合、標準でブラジルのコールサインが割り当てられます。このフィールドは、手動APRS-ISフィルター用に完全に編集可能です。",
