    "Quando chega uma nova mensagem para sua estação e a aba Mensagens já está aberta, o programa usa um aviso pequeno e não bloqueante, que fecha automaticamente pelo tempo definido em Configuração. Fora da aba Mensagens, permanece o aviso completo com opção de responder.": "お使いの端末に新しいメッセージが届き、メッセージタブが既に開いている場合、プログラムは設定で定義された時間が経過すると自動的に閉じる、小さな非ブロック通知を使用します。メッセージタブの外では、返信オプション付きの完全な通知が残ります。",
    "Quando houver atualização, clicar no aviso inicia o download do pacote compatível com a plataforma. O arquivo é validado antes da instalação.": "アップデートが利用可能になると、通知をクリックすると、お使いのプラットフォームに対応したパッケージのダウンロードが開始されます。ファイルはインストール前に検証されます。",
    "Quando houver nova versão, o cliente seleciona o pacote compatível com a plataforma, valida o download e usa um updater auxiliar para encerrar a versão atual, instalar e abrir a nova versão.": "新しいバージョンが利用可能になると、クライアントはプラットフォームと互換性のあるパッケージを選択し、ダウンロードを検証した後、補助的なアップデーターを使用して現在のバージョンを閉じ、新しいバージョンをインストールして開きます。",
    "quando necessário. A configuração oferece sugestões regionais e continua aceitando servidor manual.": "必要に応じて、設定画面は地域別の提案を行い、手動によるサーバー設定も引き続き受け付けます。",
