    "Novas estações": "Nowe stacje",
    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Nowe instalacje domyślnie używają prefiksów brazylijskich. Edytor graficzny może łączyć filtry dla Brazylii, promienia, obszaru geograficznego, prefiksów, dokładnych znaków wywoławczych i typów pakietów, zachowując jednocześnie zawsze dostęp do pola ręcznego.",
    "novo": "nowy",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "Nowy odbiorca: __ARG0__. Nie ma jeszcze żadnych zarejestrowanych rozmów z tym adresem.",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "Aplikacja pozostaje aktywna podczas przygotowywania wskaźników.",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Wyeksportowany plik zawiera kod dostępu APRS-IS w czytelnym tekście. Zachowaj go w bezpiecznym miejscu.",
    "O banco SQLite fica em:": "Baza danych SQLite znajduje się pod adresem:",
    "O botão": "Przycisk",
    "O cabeçalho informa se você está usando a": "Nagłówek informuje, czy używasz",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "Klient nie przypisuje modelu radia wyłącznie na podstawie chipsetu USB. Jeśli system Windows nie określi konkretnego modelu, interfejs wyświetla się na przykład generycznie.",
    "O compositor aceita mensagens longas. Use": "Kompozytor akceptuje długie wiadomości. Użyj",
    "O destino deixou de possuir rota RF completa no período selecionado.": "Miejsce docelowe nie posiada już kompletnej trasy RF w wybranym okresie.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi wykorzystuje tłumienie duplikatów, blokowanie pętli, ograniczanie przeskoków i kolejkę priorytetową dla wiadomości/ACK/REJ.",
    "O filtro abreviado r/RAIO exige latitude e longitude configuradas.": "Skrócony filtr r/RAIO wymaga skonfigurowania szerokości i długości geograficznej.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "Filtr APRS-IS jest pusty. W zależności od używanego serwera i portu, klient może odbierać znacznie większy wolumen ruchu, wliczając w to cały przepływ dostępny na tym połączeniu.\n\nCzy chcesz kontynuować bez filtra?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "Graf wykorzystuje wiadomości ACK/REJ i obecność RF, aby priorytetyzować użyteczny ruch i unikać zbędnych powtórzeń. Nie przepisuje arbitralnie ścieżek stron trzecich ani nie tworzy linków RF.",
    "O grupo do boletim deve ter de 1 a 5 caracteres alfanuméricos.": "Grupa biuletynów musi zawierać od 1 do 5 znaków alfanumerycznych.",
    "O grupo não possui estações.": "Grupa nie posiada żadnych stacji.",
    "O identificador do boletim/anúncio deve ser 0-9 ou A-Z.": "Identyfikator biuletynu/ogłoszenia musi składać się z cyfr 0-9 lub liter A-Z.",
    "O idioma é aplicado imediatamente à interface.": "Język jest natychmiast stosowany w interfejsie.",
    "O início precisa ser anterior ao fim.": "Początek musi nastąpić przed końcem.",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "Instalator i plik Portable EXE korzystają z tej samej lokalnej bazy danych.",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Wyeksportowany plik JSON zawiera kod dostępu APRS-IS w czytelnym tekście. Przechowuj go w bezpiecznym miejscu.",
    "O novo cálculo falhou; mantendo o último ranking válido.": "Nowe obliczenia nie powiodły się; ostatnia klasyfikacja pozostaje ważna.",
    "O pacote compatível será baixado, validado e instalado automaticamente.": "Zgodny pakiet zostanie pobrany, sprawdzony i zainstalowany automatycznie.",
    "O pacote Linux TAR.GZ não contém o executável esperado.": "Pakiet Linux TAR.GZ nie zawiera oczekiwanego pliku wykonywalnego.",
    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "Nowy szablon instalacji otrzymuje brazylijskie identyfikatory. Pole pozostaje w pełni edytowalne dla ręcznych filtrów APRS-IS.",
    "O passcode é mascarado no Log.": "Kod dostępu jest ukryty w dzienniku.",
    "o popup da estação inclui atalhos para consultar": "W okienku stacji znajdują się skróty umożliwiające konsultację",
