    "para não impedir a conexão e mostra um aviso recomendando informar a altitude real.": "aby uniknąć przerwania połączenia, wyświetla się ostrzeżenie zalecające podanie rzeczywistej wysokości.",
    "para nova linha. Mensagens maiores são divididas automaticamente sem numeração visível, preservando palavras sempre que possível; cada parte mantém confirmação própria.": "Do nowego wiersza. Większe wiadomości są automatycznie dzielone bez widocznej numeracji, zachowując słowa, gdy tylko jest to możliwe; każda część zachowuje swoje własne potwierdzenie.",
    "para selecioná-lo como destinatário e responder. Se clicar no próprio indicativo, o programa tenta selecionar o outro participante.": "aby wybrać go jako odbiorcę i odpowiedzieć. Jeśli klikniesz na swój własny wskaźnik, program spróbuje wybrać innego uczestnika.",
