    "pyserial não está instalado; KISS Serial indisponível.": "pyserial nie jest zainstalowany; KISS Serial jest niedostępny.",
    "pyserial não está instalado.": "pyserial nie jest zainstalowany.",
    "Quando chega uma nova mensagem para sua estação e a aba Mensagens já está aberta, o programa usa um aviso pequeno e não bloqueante, que fecha automaticamente pelo tempo definido em Configuração. Fora da aba Mensagens, permanece o aviso completo com opção de responder.": "Gdy na Twoją stację przychodzi nowa wiadomość, a zakładka Wiadomości jest już otwarta, program wyświetla małe, nieblokujące powiadomienie, które zamyka się automatycznie po czasie zdefiniowanym w Ustawieniach. Poza zakładką Wiadomości, pełne powiadomienie pozostaje z opcją odpowiedzi.",
    "Quando houver atualização, clicar no aviso inicia o download do pacote compatível com a plataforma. O arquivo é validado antes da instalação.": "Gdy aktualizacja będzie dostępna, kliknięcie powiadomienia rozpocznie pobieranie pakietu kompatybilnego z Twoją platformą. Plik jest weryfikowany przed instalacją.",
    "Quando houver nova versão, o cliente seleciona o pacote compatível com a plataforma, valida o download e usa um updater auxiliar para encerrar a versão atual, instalar e abrir a nova versão.": "Gdy dostępna jest nowa wersja, klient wybiera pakiet zgodny z platformą, zatwierdza pobranie i używa pomocniczego programu do aktualizacji, aby zamknąć bieżącą wersję, zainstalować i otworzyć nową wersję.",
    "quando necessário. A configuração oferece sugestões regionais e continua aceitando servidor manual.": "W razie potrzeby konfiguracja oferuje sugestie regionalne i nadal akceptuje ręczne ustawienia serwera.",
    "quando usado pela serial neste fluxo, mantenha o rádio no modo": "Używając komunikacji szeregowej w tym strumieniu, należy utrzymywać radio w trybie .",
