    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Nieuwe installaties gebruiken standaard Braziliaanse prefixen. De grafische editor kan filters combineren voor Brazilië, straal, geografisch gebied, prefixen, exacte roepnamen en pakkettypen, terwijl het handmatige veld altijd beschikbaar blijft.",
