    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "新安装的电台默认使用巴西前缀。图形编辑器可以组合使用巴西、半径、地理区域、前缀、精确呼号和数据包类型等筛选条件，同时始终保留手动输入字段。",
