    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "客户端不会仅根据 USB 芯片组来分配无线电型号。例如，当 Windows 未指定实际型号时，界面会显示通用信息。",
    "O compositor aceita mensagens longas. Use": "作曲家接受长消息。使用",
