    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi 使用重复抑制、循环阻塞、跳数限制和消息优先级队列/ACK/REJ。",
    "O filtro abreviado r/RAIO exige latitude e longitude configuradas.": "简写过滤器 r/RAIO 需要配置纬度和经度。",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "过滤器 APRS-IS 为空。根据所使用的服务器和端口，客户端可能会接收到更大的流量，包括此连接上的所有可用流量。\n\n是否要继续不使用过滤器？",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "该图使用消息（ACK/REJ）和存在状态（RF）来优先处理有用的流量，避免不必要的重复。它不会随意重写第三方路径或创建链接（RF）。",
    "O grupo do boletim deve ter de 1 a 5 caracteres alfanuméricos.": "公告组必须包含 1 到 5 个字母数字字符。",
    "O grupo não possui estações.": "该集团不拥有任何电台。",
    "O identificador do boletim/anúncio deve ser 0-9 ou A-Z.": "新闻简报/公告标识符必须为 0-9 或 A-Z。",
