    "Quando chega uma nova mensagem para sua estação e a aba Mensagens já está aberta, o programa usa um aviso pequeno e não bloqueante, que fecha automaticamente pelo tempo definido em Configuração. Fora da aba Mensagens, permanece o aviso completo com opção de responder.": "当您的电台收到新消息且“消息”选项卡已打开时，程序会显示一个小型、非阻塞式通知，该通知会在“设置”中设定的时间后自动关闭。在“消息”选项卡之外，完整的通知会保留，并提供回复选项。",
    "Quando houver atualização, clicar no aviso inicia o download do pacote compatível com a plataforma. O arquivo é validado antes da instalação.": "当有可用更新时，点击通知即可开始下载与您的平台兼容的软件包。该文件在安装前会进行验证。",
    "Quando houver nova versão, o cliente seleciona o pacote compatível com a plataforma, valida o download e usa um updater auxiliar para encerrar a versão atual, instalar e abrir a nova versão.": "当有新版本可用时，客户端选择与平台兼容的软件包，验证下载，并使用辅助更新程序关闭当前版本，安装并打开新版本。",
